/** A Font Awesome name ('car', 'fas fa-car', ['fab', 'discord']), a lucide name, or an image URL ('nui://…', 'https://…', anything with .png/.webp). */
export type IntentIcon = string | string[] | {
  prefix: string;
  iconName: string;
};

/** Any CSS colour. Prefer a theme token (var(--success)); fixed colours are for things the theme can't know. */
export type IntentColor = string;

/** Font Awesome animation. */
export type IntentIconAnimation = "spin" | "spinPulse" | "spinReverse" | "pulse" | "beat" | "fade" | "beatFade" | "bounce" | "shake";

/** Semantic tone, drawn with the theme's status tokens. */
export type IntentStatus = "info" | "success" | "warning" | "error";

/** Where on the screen, --nk-edge from the edge. 'top'/'bottom'/'left'/'right' and ox's 'right-center' are accepted aliases. */
export type IntentAnchor = "top-left" | "top-center" | "top-right" | "center-left" | "center-right" | "bottom-left" | "bottom-center" | "bottom-right" | "center" | "top" | "bottom" | "left" | "right" | "left-center" | "right-center";

/** Panel width step. */
export type IntentSize = "xs" | "sm" | "md" | "lg" | "xl";

/** Detail rows shown beside an item: strings, { label, value, progress } rows, or a { key: value } map. */
export type IntentMetadata = (string | {
  label?: string;
  value?: unknown;
  progress?: number;
  colorScheme?: string;
})[] | Record<string, unknown>;

/** A preset, or a custom zone: areaSize in degrees and speedMultiplier (1 = one turn in 2 s). */
export type IntentDifficulty = "easy" | "medium" | "hard" | {
  areaSize: number;
  speedMultiplier: number;
};

